import './contact.css';
import react,{useRef} from "react";
import emailjs from '@emailjs/browser';
// import { ScrollDown } from './scrolldown';
export function Contact(){
    const form=useRef();
    const sendEmail=(e)=>{
        e.preventDefault();
        emailjs.sendForm('service_jhnsvww','template_s2yvsbb',form.current,'DhHImJwVvadAQohx2')
        // .then((result)=>{
        //     console.log(result.text);
        // }, (error)=>{
        //     console.log(error.text);
        // });
        e.target.reset()
    };
    return(
        <div>
        <section style={{display:'grid', placeItems:'center'}} className="contact section" id='contact'>
            <h2 className="section__title">Get in touch</h2>
            <span className="section__subtitle">Contact Me</span>
            <div className="contact__container container grid">
                <div className="contact__content">
                    <h3 className="contact__title">Talk to me</h3>
                    <div className="contact__info">
                        <div className="contact__card">
                            <i className="bx bx-mail-send contact__card-icon"></i>
                            <h3 className="contact__card-title">Email</h3>
                            <span className="contact__card-data">nikithavedanth@gmail.com</span>
                            <a href='https://mail.google.com/' className="contact__button">Write me <i className="bx bx-right-arrow-alt contact__button-icon"></i></a>
                        </div>
                        <div className="contact__card">
                            <i className="bx bxl-whatsapp contact__card-icon"></i>
                            <h3 className="contact__card-title">Whatsapp No.</h3>
                            <span className="contact__card-data">+15105989909</span>
                            <a href='https://web.whatsapp.com/' className="contact__button">Write me <i className="bx bx-right-arrow-alt contact__button-icon"></i></a>
                        </div>
                        <div className="contact__card">
                            <i className="bx bxl-linkedin contact__card-icon"></i>
                            <h3 className="contact__card-title">LinkedIn</h3>
                            <span className="contact__card-data">https://www.linkedin.com/in/nikitha-vedant-madabhushi-0643b1182/</span>
                            <a href='https://www.linkedin.com/in/nikitha-vedant-madabhushi-0643b1182/' className="contact__button">Write me <i className="bx bx-right-arrow-alt contact__button-icon"></i></a>
                        </div>
                    </div>
                </div>
                <div className="contact__content">
                    <h3 className="contact__title">Write me your project</h3>
                    <form ref={form} onSubmit={sendEmail}className='contact__form'>
                        <div className="contact__form-div">
                            <label htmlFor="" className="contact__form-tag">Name</label>
                            <input type="text" name="name" className="contact__form-input" placeholder="Insert your name"/>
                        </div>
                        <div className="contact__form-div">
                            <label htmlFor="" className="contact__form-tag">Mail</label>
                            <input type="email" name="email" className="contact__form-input" placeholder="Insert your email"/>
                        </div>
                        <div className="contact__form-div contact__form-area">
                            <label htmlFor="" className="contact__form-tag">Project</label>
                            {/* <input type="text" name="name" className="contact__form-input" placeholder="Insert your name"/> */}
                            <textarea name="project" cols='30' rows='10' className="contact__form-input" placeholder="Write your project"></textarea>
                        </div>
                     <button className="btn btn-info button button--flex uil uil-message">Send Message
                    {/* <svg
                  className="button__icon"
                  xmlns="http://www.w3.org/2000/svg"
                  width="24"
